_MODE = make_sentinel('_MODE')


class Auto(object):
    """Evaluate a subspec using glom's normal specification semantics."""
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        scope[_MODE] = Auto
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        return 'Auto(%r)' % (self.spec,)


class Fill(object):
    """Build containers literally, evaluating embedded specifiers and callables.

    Unlike normal glom mode, strings are literal values and tuples and lists
    describe output containers rather than pipelines and iteration.
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        scope[_MODE] = Fill
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        return 'Fill(%r)' % (self.spec,)


def _fill(target, spec, scope):
    recurse = lambda value: scope[glom](target, value, scope)
    if isinstance(spec, dict):
        return type(spec)((recurse(k), recurse(v)) for k, v in spec.items())
    if isinstance(spec, (list, tuple, set, frozenset)):
        return type(spec)(recurse(v) for v in spec)
    if callable(spec):
        return spec(target)
    return spec


class Let(object):
    """Bind named subspec results in the current scope, keeping the target."""
    def __init__(self, **bindings):
        self.bindings = bindings

    def glomit(self, target, scope):
        values = {name: scope[glom](target, spec, scope)
                  for name, spec in self.bindings.items()}
        scope.maps[1].update(values)
        return target

    def __repr__(self):
        return 'Let(%s)' % ', '.join('%s=%r' % item
                                    for item in self.bindings.items())

